	if !atomic.CompareAndSwapInt32(&r.done, 0, 1) {
		return nil
	}

	// Delete the newly-created credential.
	if err := native.DeleteNonInteractive(r.credentialID); err != nil {
		return err
	}
	r.credentialID = ""
	return nil
}`

